namespace StarlightSyndicateDemo;
public static class DefenseTests
{
 static int checks;
 static void Check(bool ok,string label){if(!ok)throw new Exception("DEFENSE FAIL: "+label);checks++;Console.WriteLine("DEFENSE PASS: "+label);}
 static DemoWorld World(string hull="battleship") {var w=new DemoWorld();w.NewGame(0);w.DefenseTrial(hull);w.Credits=100000;return w;}
 static DefenseDefinition Def(string kind,int size=-1)=>DefenseCatalog.All.First(d=>d.Kind==kind&&(size<0||d.Size==size));
 static int Slot(DefenseDefinition d)=>d.Slot=="high"?0:d.Slot=="medium"?1:6;
 static string Hull(DefenseDefinition d)=>d.Role=="Assault"?"assault":d.Role=="Nullifiable"?"interceptor":d.Role=="Battleship"?"battleship":d.Size==4?"titan":"battleship";
 public static void Run()
 {
  Check(DefenseCatalog.All.Length==83&&DefenseCatalog.All.Select(d=>d.Id).Distinct().Count()==83,"All 83 requested size / function profiles have unique identities");
  Check(DefensePayloads.All.Length==18,"Cells, paste and eight reusable resistance scripts");
  foreach(var d in DefenseCatalog.All)
  {
   var w=World(Hull(d));var p=w.Player;int index=Slot(d);var baseline=ShipAttributeCatalog.All.Where(a=>a.Group!="Derived").ToDictionary(a=>a.Key,a=>p.Stat(a.Key));float count=w.ItemCount(d.Id,true);
   Check(w.FitDefense(d.Id,true,index),"Fit / "+d.Name);
   Check(w.ItemCount(d.Id,true)==count-1&&p.Defense[index].ModuleId==d.Id&&p.Stat("cpuLoad")>=44+d.Cpu-.01,"Real stock and shared budget / "+d.Name);
   var s=p.Defense[index];var payload=DefensePayloads.For(d).FirstOrDefault();if(payload!=null)Check(w.LoadDefensePayload(index,payload.Id)&&s.Loaded>0,"Compatible payload / "+d.Name);
   if(!d.Active)
   {
    Check(baseline.Any(a=>a.Key is not ("cpuLoad" or "powerLoad")&&Math.Abs(p.Stat(a.Key)-a.Value)>.0001),"Live passive effect / "+d.Name);
   }
   else
   {
    w.Undock();p.Shield=p.MaxShield*.1f;p.Armor=p.MaxArmor*.1f;p.Hull=p.MaxHull*.1f;p.Cap=p.MaxCap*.6f;s.Repeat=false;s.AutoReload=false;
    var before=ShipAttributeCatalog.All.Where(a=>a.Group!="Derived").ToDictionary(a=>a.Key,a=>p.Stat(a.Key));float shield=p.Shield,armor=p.Armor,hull=p.Hull,cap=p.Cap;
    Check(w.ToggleDefense(index),"Activate / "+d.Name);
    bool effect=d.Kind switch
    {"ShieldBoost" or "AncillaryShield"=>p.Shield>shield,"ArmorRepair" or "AncillaryArmor" or "HullRepair"=>s.PendingRepair>0&&p.Armor==armor&&p.Hull==hull,"CapBooster"=>p.Cap>cap,"Nullifier"=>p.Stat("warpBubbleImmune")>0,"Stabilizer"=>p.Stat("warpCoreStrength")>0,"Suppressor"=>p.Signature<before["signatureRadius"],_=>before.Any(a=>a.Key.Contains("Resonance")&&p.Stat(a.Key)<a.Value)};
    Check(effect,"Live active effect / "+d.Name);
    if(d.DelayedRepair){w.UpdateDefense(d.Cycle+1);Check(d.Kind=="HullRepair"?p.Hull>hull:p.Armor>armor,"Repair completes at cycle end / "+d.Name);}
    if(d.Kind=="Emergency"){w.UpdateDefense(d.Cycle+1);Check(s.Burnt&&!w.ToggleDefense(index),"Emergency energizer burns out after one use");}
   }
   w.Screen=ViewMode.Station;Check(w.UnfitDefense(index)&&w.ItemCount(d.Id,true)==count,"Unfit returns real module / "+d.Name);
  }
  var w1=World();var d1=Def("AncillaryArmor",1);Check(w1.FitDefense(d1.Id,true,6),"Fit ancillary armor");Check(!w1.FitDefense(Def("AncillaryArmor",2).Id,true,7),"Ancillary armor one-per-ship restriction");
  Check(w1.FitDefense(Def("DamageControl").Id,true,7)&&!w1.FitDefense(Def("Emergency").Id,true,8),"Damage controls share one fitting group");
  var small=World("frigate");Check(!small.FitDefense(Def("ShieldBoost",4).Id,true,1),"Capital size restricted");Check(!small.FitDefense(Def("AssaultControl").Id,true,6),"Assault hull restriction");Check(!small.FitDefense(Def("Suppressor").Id,true,1),"Signature suppressor restricted to battleship");Check(!small.FitDefense(Def("Nullifier").Id,true,0),"Nullifier requires compatible hull");
  Check(!small.FitDefense(Def("ArmorRepair",1).Id,true,1),"Wrong socket rejected");
  var budget=World("frigate");budget.Player.SetStat("cpuOutput",45);float stock=budget.ItemCount(Def("ShieldBoost",1).Id,true);Check(!budget.FitDefense(Def("ShieldBoost",1).Id,true,1)&&budget.ItemCount(Def("ShieldBoost",1).Id,true)==stock,"Budget rejection preserves inventory");
  var shared=World("cruiser");var hard=Def("ShieldHardener");shared.Hangar[hard.Id]=5;for(int i=1;i<6;i++)Check(shared.FitDefense(hard.Id,true,i),"Shared mid socket "+i);Check(!shared.FitEwar(EwarCatalog.All.First(e=>e.Kind==EwarKind.Web).Id,true,1),"EWAR cannot exceed shared medium sockets");
  var r=World();var rep=Def("ArmorRepair",1);r.FitDefense(rep.Id,true,6);r.Undock();r.Player.Armor=1;var rs=r.Player.Defense[6];rs.Repeat=false;r.ToggleDefense(6);Check(r.Player.Armor==1&&rs.PendingRepair>0,"Armor is not repaired at cycle start");r.UpdateDefense(rep.Cycle*.5f);Check(r.Player.Armor==1,"Armor remains damaged midway through cycle");r.ToggleDefense(6);r.UpdateDefense(rep.Cycle*.6f);Check(r.Player.Armor>1&&!rs.Active,"Deactivation finishes paid repair cycle");
  var validFuel=World();validFuel.FitDefense(Def("AncillaryShield",3).Id,true,1);Check(!validFuel.LoadDefensePayload(1,"dc_25")&&validFuel.LoadDefensePayload(1,"dc_150"),"Ancillary shield requires size-specific fuel cells, not merely a volume fit");
  var ash=World();var asd=Def("AncillaryShield",1);ash.FitDefense(asd.Id,true,1);ash.LoadDefensePayload(1,"dc_25");ash.Undock();var ass=ash.Player.Defense[1];ass.AutoReload=false;ass.Repeat=false;ash.Player.Cap=0;ash.Player.Shield=1;int cells=ass.Loaded;Check(ash.ToggleDefense(1)&&ash.Player.Cap==0&&ass.Loaded==cells-1,"Charged ancillary shield runs without capacitor and consumes one cell");ash.UpdateDefense(asd.Cycle+1);ass.Loaded=0;Check(!ash.ToggleDefense(1),"Dry ancillary shield cannot activate without capacitor");ash.Player.Cap=asd.Capacitor*2;float asCap=ash.Player.Cap;Check(ash.ToggleDefense(1)&&ash.Player.Cap<asCap,"Dry ancillary shield uses high capacitor cost");
  var aar=World();aar.FitDefense(Def("AncillaryArmor",2).Id,true,6);aar.LoadDefensePayload(6,"dc_paste");aar.Undock();var aars=aar.Player.Defense[6];aars.Loaded=2;aars.AutoReload=false;aars.Repeat=false;aar.Player.Cap=aar.Player.MaxCap;aar.ToggleDefense(6);Check(aars.Loaded==0&&Math.Abs(aars.PendingRepair-aars.Definition!.Amount*2)<.01,"Partial paste scales armor repair bonus proportionally");
  var capw=World();capw.FitDefense(Def("CapBooster",1).Id,true,1);float beforeCount=capw.ItemCount("dc_200",true);capw.LoadDefensePayload(1,"dc_200");var cs=capw.Player.Defense[1];Check(cs.Loaded==1&&capw.ItemCount("dc_200",true)==beforeCount-1,"Cell volume determines injector magazine capacity");Check(!capw.LoadDefensePayload(1,"dc_800"),"Oversize cell rejected");capw.ProvisionDefenseCargo(1);capw.Undock();cs.Repeat=true;capw.Player.Cap=0;capw.ToggleDefense(1);Check(capw.Player.Cap==Math.Min(capw.Player.MaxCap,DefensePayloads.ById["dc_200"].Amount)&&cs.Loaded==0,"Injector caps actual GJ at capacity");capw.UpdateDefense(cs.Definition!.Cycle+.1f);Check(cs.ReloadLeft>0&&cs.Loaded>0,"Automatic reload reserves real cargo cells");float during=capw.Player.Cap;capw.UpdateDefense(5);Check(capw.Player.Cap==during,"Injector waits during reload");
  var adapt=World();adapt.FitDefense(Def("Reactive").Id,true,6);adapt.Undock();adapt.Player.Shield=0;adapt.Player.Cap=adapt.Player.MaxCap;adapt.ToggleDefense(6);var ad=adapt.Player.Defense[6];float initial=ad.ReactiveResists[1];adapt.DefensePressure(100,DamageType.Thermal);adapt.UpdateDefense(ad.Definition!.Cycle+.1f);Check(ad.ReactiveResists[1]>initial&&Math.Abs(ad.ReactiveResists.Sum()-.54f)<.001,"Reactive membrane shifts a conserved resistance pool toward armor damage");adapt.ToggleDefense(6);adapt.UpdateDefense(ad.Definition.Cycle+1);adapt.ToggleDefense(6);Check(ad.ReactiveResists.All(x=>Math.Abs(x-.135f)<.001),"Reactive adaptation resets on restart");
  var shieldOnly=World();shieldOnly.FitDefense(Def("Reactive").Id,true,6);shieldOnly.Undock();shieldOnly.ToggleDefense(6);shieldOnly.DefensePressure(20,DamageType.EM);Check(shieldOnly.Player.Defense[6].Incoming.Sum()==0,"Shield-only damage does not adapt armor hardener");
  var flex=World("titan");var fd=Def("FlexArmor");flex.FitDefense(fd.Id,true,6);flex.LoadDefensePayload(6,"dc_armor_em");flex.Undock();float thermal=flex.Player.Resistance("armor",DamageType.Thermal),em=flex.Player.Resistance("armor",DamageType.EM);flex.ToggleDefense(6);Check(flex.Player.Resistance("armor",DamageType.EM)>em&&flex.Player.Resistance("armor",DamageType.Thermal)==thermal,"Flex script concentrates defense and removes other bonuses");int script=flex.Player.Defense[6].Loaded;flex.UpdateDefense(fd.Cycle*2.1f);Check(flex.Player.Defense[6].Loaded==script,"Resistance scripts are reusable");
  var stack=World();float baseRes=stack.Player.Resistance("armor",DamageType.EM);var coat=Def("Coating");stack.FitDefense(coat.Id,true,6);float first=stack.Player.Resistance("armor",DamageType.EM);stack.FitDefense(coat.Id,true,7);float second=stack.Player.Resistance("armor",DamageType.EM);Check(first>baseRes&&second>first&&(1-second)/(1-first)>coat.Resonances["armorEmDamageResonance"],"Resistance stacking penalty reduces second module effectiveness");
  var battery=World();float capbase=battery.Player.MaxCap;float resist=battery.Player.Stat("energyWarfareResistance") is double v?(float)v:1;battery.FitDefense(Def("Battery",1).Id,true,1);Check(battery.Player.MaxCap>capbase&&battery.Player.Stat("energyWarfareResistance")<resist,"Battery adds capacitor storage and hostile drain resistance");battery.Undock();float full=battery.Player.Cap;battery.DefenseNeutPressure(100);Check(Math.Abs(full-battery.Player.Cap-100*battery.Player.Stat("energyWarfareResistance"))<.01,"Battery mitigates actual capacitor pressure");
  var escape=World("interceptor");escape.FitDefense(Def("Nullifier").Id,true,0);escape.Undock();escape.EwarZones.Add(new(){Kind=EwarKind.Sphere,Center=escape.Player.Position,Radius=1000,Remaining=100});Check(escape.WarpBlocked("player"),"Bubble blocks ship before nullifier");escape.ToggleDefense(0);Check(!escape.WarpBlocked("player"),"Activated nullifier permits bubble escape");escape.EwarEffects.Add(new(){SourceId="player",TargetId="player",Kind=EwarKind.Point,Strength=1,Remaining=100});Check(escape.WarpBlocked("player"),"Nullifier does not defeat targeted tackle");escape.UpdateDefense(Def("Nullifier").Cycle*2+1);Check(!escape.ToggleDefense(0),"Nullifier enforces reactivation delay");
  var stab=World();float sensor=stab.Player.Stat("maxTargetRange") is double vv?(float)vv:0;stab.FitDefense(Def("Stabilizer").Id,true,6);Check(stab.Player.Stat("maxTargetRange")<sensor&&stab.Player.Stat("droneBandwidth")<125,"Warp stabilization carries permanent sensor and drone penalties");stab.Undock();stab.EwarEffects.Add(new(){SourceId="player",TargetId="player",Kind=EwarKind.Scram,Strength=2,Remaining=100});Check(stab.WarpBlocked("player"),"Targeted tackle blocks unstabilized warp");stab.ToggleDefense(6);Check(!stab.WarpBlocked("player")&&!stab.CanUseMicroDrive("player"),"Warp strength permits escape but scram still disables micro drives");stab.EwarZones.Add(new(){Kind=EwarKind.Sphere,Center=stab.Player.Position,Radius=1000,Remaining=100});Check(stab.WarpBlocked("player"),"Stabilizer does not grant bubble immunity");
  var heat=World();heat.FitDefense(rep.Id,true,6);heat.Undock();heat.Player.Defense[6].Overheat=true;heat.Player.Armor=1;heat.ToggleDefense(6);Check(heat.Player.Defense[6].PendingRepair>rep.Amount&&heat.Player.Defense[6].CycleLeft<rep.Cycle,"Overload accelerates repair and increases amount with heat damage");heat.UpdateDefense(rep.Cycle*20);Check(heat.Player.Defense[6].Burnt,"Repeated overload burns module out");heat.Screen=ViewMode.Station;heat.UnfitDefense(6);heat.FitDefense(rep.Id,true,6);Check(heat.Player.Defense[6].Burnt,"Unfit/refit preserves module condition");Check(heat.RepairDefense(6)&&!heat.Player.Defense[6].Burnt,"Station repair restores burnt defense module");
  var save=World();save.FitDefense(Def("AncillaryArmor",1).Id,true,6);save.LoadDefensePayload(6,"dc_paste");save.Undock();save.Player.Armor=1;var ss=save.Player.Defense[6];ss.AutoReload=false;ss.Repeat=false;save.ToggleDefense(6);save.UpdateDefense(1);save.Save();var loaded=new DemoWorld();Check(loaded.Load(),"Defense save loads");var ls=loaded.Player.Defense[6];Check(ls.Loaded==ss.Loaded&&ls.PendingRepair==ss.PendingRepair&&ls.CycleLeft==ss.CycleLeft&&!ls.AutoReload&&!ls.Repeat,"Magazine, pending repair, timers and controls persist");float hpBefore=loaded.Player.Armor;loaded.UpdateDefense(ls.CycleLeft+1);Check(loaded.Player.Armor>hpBefore&&ls.PendingRepair==0,"Saved pending repair completes once");
  var sigw=World();sigw.FitDefense(Def("Suppressor").Id,true,1);sigw.EnterDefenseRange();sigw.Player.Velocity=new(0,0,300);var attacker=sigw.Targets.First();attacker.Position=new(4000,0,0);float gunBefore=sigw.DefenseIncomingGunChance(attacker),lockBefore=sigw.DefenseNpcLockSeconds(attacker,"player");sigw.ToggleDefense(1);Check(sigw.DefenseIncomingGunChance(attacker)<gunBefore&&sigw.DefenseNpcLockSeconds(attacker,"player")>lockBefore,"Signature suppression reduces gun application and lengthens hostile lock time");
  var penalized=World();penalized.FitDefense(Def("Stabilizer").Id,true,6);penalized.EnterDefenseRange();penalized.SelectedId="range_0";penalized.LockTarget();Check(penalized.PendingLockId=="range_0"&&penalized.LockTimeLeft>1.5,"Fitted stabilization scan penalty affects actual acquisition time");
  var ampw=World();ampw.FitDefense(Def("ShieldBoost",1).Id,true,1);ampw.FitDefense(Def("BoostAmplifier").Id,true,2);ampw.Undock();ampw.Player.Shield=1;var ampstate=ampw.Player.Defense[1];ampstate.Overheat=true;ampw.ToggleDefense(1);Check(ampw.Player.Shield>1+ampstate.Definition!.Amount*1.1&&ampstate.Damage>ampstate.Definition.HeatDamage/ampstate.Definition.ModuleHp,"Boost amplifier improves actual repair and amplifies shield overload damage");
  var actual=World();actual.FitDefense(Def("Battery",1).Id,true,1);actual.EnterDefenseRange();var ne=EwarCatalog.All.First(d=>d.Kind==EwarKind.Neutralizer) with{Amount=100,Optimal=10000};float actualBefore=actual.Player.Cap;actual.ApplyEwarCycle(ne,"range_0","player","battery_test");Check(Math.Abs(actualBefore-actual.Player.Cap-100*actual.Player.Stat("energyWarfareResistance"))<.1,"Battery resistance is used by live hostile EWAR neutralization");
  var blocker=World("interceptor");blocker.FitDefense(Def("Nullifier").Id,true,0);var jammer=EwarCatalog.All.First(d=>d.Kind==EwarKind.BurstJam);blocker.FitEwar(jammer.Id,true,1);blocker.EnterDefenseRange();Check(blocker.Player.Ewar[1].Definition?.Kind==EwarKind.BurstJam&&!blocker.ToggleDefense(0),"Fitted burst jammer disables nullifier activation");
  var condition=World();condition.FitDefense(rep.Id,true,6);condition.Player.Defense[6].Damage=.5f;condition.UnfitDefense(6);condition.TransferItem(rep.Id,true,1);Check(condition.DefenseStorage.Any(x=>!x.Hangar&&x.State.Damage==.5f),"Inventory movement preserves damaged module metadata");condition.Save();var savedCondition=new DemoWorld();Check(savedCondition.Load()&&savedCondition.DefenseStorage.Any(x=>!x.Hangar&&x.State.Damage==.5f),"Stored module condition survives save/load");Check(savedCondition.SubmitMarket(rep.Id,savedCondition.SystemId,false,1,1,1,false).Contains("Repair"),"Market blocks selling unrepaired damaged module stacks");Check(savedCondition.RepairStoredDefenses()&&savedCondition.DefenseStorage.All(x=>x.State.Damage==0&&!x.State.Burnt),"Paid station service repairs stored damaged modules");
  var dockTimers=World();dockTimers.Player.Defense[1]=DefenseState.Create(Def("ShieldBoost",1).Id);dockTimers.Player.Defense[1].ReloadLeft=10;dockTimers.Player.Defense[1].ReactivationLeft=20;dockTimers.Update(5);Check(dockTimers.Player.Defense[1].ReloadLeft==5&&dockTimers.Player.Defense[1].ReactivationLeft==15,"Docked reload and reactivation timers continue to elapse");
  var oversize=World("frigate");Check(oversize.FitDefense(Def("ShieldBoost",2).Id,true,1),"Oversized subcapital shield module allowed when CPU/grid and sockets permit");
  var capLimit=World("titan");capLimit.FitDefense(Def("AncillaryShield",4).Id,true,1);Check(!capLimit.FitDefense(Def("AncillaryShield",1).Id,true,2),"Capital ancillary shield limit also prevents adding smaller chassis");
  Console.WriteLine($"{checks} defense and capacitor checks passed.");
 }
}
